Path: ios/Lumen/Services/DeterministicToolPlanner.swift Module: Services Language: swift Source hash: c5475403c87c1c9708932642f38e660d8ab23d19f9eb889a2a6b771695604429 Chunk hash: 6e86f933f64b26366208f7cb8b6c8a7a8a0c81b5ce0fe75b8b50cd2818802bb2 Lines: 462-507 Source: private static func lookupAlarmUUIDByTitle(_ title: String) -> String? { #if canImport(AlarmKit) if #available(iOS 26.0, *) { do { let alarms = try AlarmManager.shared.alarms let matches = alarms.filter { alarm in String(describing: alarm).localizedCaseInsensitiveContains(title) || (Mirror(reflecting: alarm).children.first { $0.label == "title" }?.value as? String)?.localizedCaseInsensitiveCompare(title) == .orderedSame } if matches.count == 1, let alarm = matches.first, let id = Mirror(reflecting: alarm).children.first(where: { $0.label == "id" })?.value as? UUID { return id.uuidString } } catch { return nil } } #endif return nil } private static func firstUUID(in text: String) -> String? { AlarmCommandClassifier.firstUUID(in: text) } private static func extractAlarmTitle(from prompt: String, fallback: String) -> String { if let named = firstCapture(in: prompt, pattern: #"(?i) (?:named|called)\s+([^.!?
]+)"#) { var cleaned = cleanCapturedValue(named) if let range = cleaned.range(of: #"(?i)\s+(?:for|in)\s+\d+\s+(?:seconds?|minutes?|hours?|days?) "#, options: .regularExpression) { cleaned = String(cleaned[..<range.lowerBound]).trimmingCharacters(in: .whitespacesAndNewlines) } if !cleaned.isEmpty { return cleaned } } return fallback } private static func extractTriggerCancelIdentifier(from prompt: String) -> String { if let uuid = firstUUID(in: prompt) { return uuid } if let named = firstCapture(in: prompt, pattern: #"(?i) (?:named|called)\s+([^.!?
]+)"#) { return cleanCapturedValue(named) } if let trigger = firstCapture(in: prompt, pattern: #"(?i) cancel\s+(?:the\s+)?(?:trigger|scheduled run|agent run)\s+([^.!?
]+)"#) { return cleanCapturedValue(trigger) } return "" } private static func extractTriggerTitle(from prompt: String) -> String { let lower = normalized(prompt) if lower.contains("reminder") { return "Reminder summary" } if lower.contains("digest") { return "Scheduled digest" } return "Scheduled agent run" }

